package vn.covie.cart.application;
import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.auth.security.CurrentActorProvider; import vn.covie.cart.api.dto.*; import vn.covie.cart.model.*; import vn.covie.cart.persistence.*; import vn.covie.catalog.model.*; import vn.covie.catalog.persistence.*; import vn.covie.merchants.persistence.MerchantLocationRepository; import vn.covie.shared.id.UuidV7Generator; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;
@Service public class CartService{private final vn.covie.users.persistence.UserRepository users;private final CurrentActorProvider actors;private final CartRepository carts;private final CartItemRepository items;private final LocationVariantRepository offers;private final VariantRepository variants;private final CatalogItemRepository catalog;private final MerchantLocationRepository locations;private final CartItemSnapshotFactory snapshots;private final UuidV7Generator ids;private final AppClock clock;public CartService(CurrentActorProvider actors,CartRepository carts,CartItemRepository items,LocationVariantRepository offers,VariantRepository variants,CatalogItemRepository catalog,MerchantLocationRepository locations,CartItemSnapshotFactory snapshots,UuidV7Generator ids,AppClock clock,vn.covie.users.persistence.UserRepository users){this.users=users;this.actors=actors;this.carts=carts;this.items=items;this.offers=offers;this.variants=variants;this.catalog=catalog;this.locations=locations;this.snapshots=snapshots;this.ids=ids;this.clock=clock;}@Transactional(readOnly=true)public List<CartResponse> list(){return carts.findByUserIdAndCartStatusOrderByUpdatedAtDesc(actors.currentActor().userId(),CartStatus.ACTIVE).stream().map(this::response).toList();}@Transactional public CartResponse add(AddCartItemRequest req){if(req==null||req.locationVariantId()==null||req.quantity()<1)throw invalid("Quantity and locationVariantId are required.");var actor=actors.currentActor().userId();var offer=offers.findUsableById(req.locationVariantId()).orElseThrow(CartService::notFound);var variant=variants.findById(offer.getVariantId()).orElseThrow(CartService::notFound);var item=catalog.findById(variant.getCatalogItemId()).orElseThrow(CartService::notFound);var location=locations.findById(offer.getMerchantLocationId()).orElseThrow(CartService::notFound);CartType type=item.getItemType()==CatalogItemType.SERVICE?CartType.SERVICE:CartType.PRODUCT;if(type==CartType.SERVICE&&req.quantity()!=1)throw invalid("Service quantity must be exactly one.");users.findByIdForUpdate(actor).orElseThrow(CartService::notFound);CartEntity cart=carts.findByUserIdAndMerchantLocationIdAndCartTypeAndCartStatus(actor,location.getId(),type,CartStatus.ACTIVE).orElseGet(()->carts.save(CartEntity.active(ids.generate(),actor,location.getId(),type,clock.now())));CartItemEntity line=items.findByCartIdAndLocationVariantId(cart.getId(),offer.getId()).orElse(null);if(line==null)items.save(CartItemEntity.create(ids.generate(),cart.getId(),offer.getId(),variant.getId(),req.quantity(),offer.getPrice(),offer.getCurrencyCode(),item.getName(),snapshots.snapshot(variant),clock.now()));else{if(type==CartType.SERVICE)throw invalid("Service quantity must be exactly one.");line.increment(req.quantity(),clock.now());items.save(line);}cart.touch(clock.now());carts.saveAndFlush(cart);return response(cart);}@Transactional(readOnly=true)public CartResponse get(UUID cartId){return carts.findById(cartId).filter(c->c.getUserId().equals(actors.currentActor().userId())&&c.getCartStatus()==CartStatus.ACTIVE).map(this::response).orElseThrow(CartService::notFound);}private CartResponse response(CartEntity c){return new CartResponse(c.getId(),c.getMerchantLocationId(),c.getCartType(),c.getVersion(),items.findByCartIdOrderByAddedAtAsc(c.getId()).stream().map(i->new CartItemResponse(i.getId(),i.getLocationVariantId(),i.getQuantity(),i.getPriceSnapshot(),i.getItemNameSnapshot())).toList());}private static ApiException invalid(String m){return new ApiException(ErrorCode.CART_ITEM_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,m);}private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");}}
